  #root { display:flex; flex-direction:column; width:100%; height:100%; min-width:0; min-height:0; background:var(--bg); color:var(--ink); font-family:var(--font-sans); }
  #treeSvg { flex:1; width:100%; height:100%; max-width:600px; display:block; }
  .controls { display:flex; align-items:center; gap:12px; padding:8px 16px; border-top:1px solid var(--line); flex-shrink:0; }
  #insertBtn { padding:6px 16px; border:1px solid var(--line); border-radius:6px; background:var(--bg2); color:var(--ink); cursor:pointer; font-size:14px; transition:background .15s, transform .1s; font-family:var(--font-sans); }
  #insertBtn:hover { filter:brightness(1.15); }
  #insertBtn:active { transform:scale(.97); }
  #insertBtn:disabled { opacity:.5; cursor:default; filter:none; transform:none; }
  .readout { font-family:var(--font-mono); font-variant-numeric:tabular-nums; font-size:13px; color:var(--text2); }
</style>
<div id="root">
  <svg id="treeSvg" viewBox="0 0 800 200" preserveAspectRatio="xMidYMid meet"></svg>
  <div class="controls">
    <button id="insertBtn">插入节点</button>
    <span class="readout">已插入: <span id="insertedCount">1</span></span>
    <span class="readout">高度: <span id="heightDisplay">1</span></span>
  </div>
</div>
<script>
  (function() {
    var step = 1;
    var svg = document.getElementById('treeSvg');
    var insertBtn = document.getElementById('insertBtn');
    var insertedCount = document.getElementById('insertedCount');
    var heightDisplay = document.getElementById('heightDisplay');

    function getTreeData(s) {
      var nodes = [];
      var edges = [];
      for (var i = 1; i <= s; i++) {
        var x = 400 + (i - 1) * 80;
        var y = 100;
        nodes.push({value: i, x: x, y: y, isNew: i === s});
        if (i > 1) {
          edges.push({from: i - 1, to: i});
        }
      }
      return {nodes: nodes, edges: edges};
    }

    console.assert(getTreeData(1).nodes.length === 1, 'step=1 should have 1 node');
    console.assert(getTreeData(1).edges.length === 0, 'step=1 should have 0 edges');
    console.assert(getTreeData(3).nodes.length === 3, 'step=3 should have 3 nodes');
    console.assert(getTreeData(3).edges.length === 2, 'step=3 should have 2 edges');

    function update() {
      svg.innerHTML = '';
      var data = getTreeData(step);
      for (var e = 0; e < data.edges.length; e++) {
        var edge = data.edges[e];
        var fromNode = data.nodes[edge.from - 1];
        var toNode = data.nodes[edge.to - 1];
        var line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', fromNode.x + 25);
        line.setAttribute('y1', fromNode.y);
        line.setAttribute('x2', toNode.x - 25);
        line.setAttribute('y2', toNode.y);
        line.style.stroke = 'var(--line)';
        line.setAttribute('stroke-width', '2');
        svg.appendChild(line);
      }
      for (var n = 0; n < data.nodes.length; n++) {
        var node = data.nodes[n];
        var circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circle.setAttribute('cx', node.x);
        circle.setAttribute('cy', node.y);
        circle.setAttribute('r', 25);
        circle.style.fill = node.isNew ? 'var(--accent)' : 'var(--bg2)';
        circle.style.stroke = 'var(--line)';
        circle.setAttribute('stroke-width', '1.5');
        svg.appendChild(circle);
        var text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        text.setAttribute('x', node.x);
        text.setAttribute('y', node.y);
        text.setAttribute('text-anchor', 'middle');
        text.setAttribute('dominant-baseline', 'central');
        text.style.fill = node.isNew ? 'var(--bg)' : 'var(--ink)';
        text.style.fontSize = '16px';
        text.style.fontFamily = 'var(--font-mono)';
        text.textContent = node.value;
        svg.appendChild(text);
      }
      insertedCount.textContent = step;
      heightDisplay.textContent = step;
      insertBtn.disabled = (step >= 5);
    }

    insertBtn.addEventListener('click', function() {
      if (step < 5) {
        step++;
        update();
      }
    });

    update();
  })();
